use std::fs

fn parse(line: string) -> string {
    let chars: Vec<char> = line.chars().collect()
    let n: int = chars.len() as int
    let mut fields: Vec<string> = []
    let mut cur: string = ""
    let mut inq = false
    let mut i: int = 0
    while i < n {
        let c = chars[i]
        if inq {
            if c == '"' {
                if i + 1 < n && chars[i + 1] == '"' {
                    cur = cur + "\""
                    i += 1
                } else {
                    inq = false
                }
            } else {
                cur = cur + c.to_string()
            }
        } else if c == '"' {
            inq = true
        } else if c == ',' {
            fields.push(cur)
            cur = ""
        } else {
            cur = cur + c.to_string()
        }
        i += 1
    }
    fields.push(cur)
    let cnt: int = fields.len() as int
    let parts: Vec<string> = fields.map(|f| "[${f}]").collect()
    "${cnt}: ${parts.join("|")}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        println(parse(line))
    }
}

